function GetRewardNewbie()
    local TableInfo = BattlePassRewards
    for Type, Table in pairs(BattlePassRewardsNewbie) do
        for k, v in pairs(Table) do
            TableInfo[Type][v.Level] = v
        end
    end
    return TableInfo
end
